{
  "technical_and_design_decisions": [
    "Target runtime is Java 17+ using Spring Framework 6.x / Spring Batch / Spring Integration paradigms.",
    "CodeGen (U1) and Merge (U2) options will be modeled as fluent builder classes and externalized configuration properties to allow dynamic parameterization at runtime.",
    "Job timeout mechanism (U3) will utilize Spring TaskScheduler and Java Concurrency primitives (CompletableFuture / ScheduledExecutorService) to gracefully interrupt hung job threads.",
    "SQL execution (U4) will be implemented as a dedicated Spring Batch ItemProcessor and Tasklet wrapping ResourceDatabasePopulator and NamedParameterJdbcTemplate.",
    "JDBC Tuple enrichment (U5) will be enabled by refactoring ItemReaderFactory and NameColumnJdbcItemReader to accept custom RowMapper<Tuple> implementations directly.",
    "Dynamic directory and file naming (U6) will leverage Spring Expression Language (SpEL) evaluated against job parameters, step execution context, and record payloads.",
    "Delimiter escaping (U7) will add a configurable escapeCharacter property to the FlatFileItemWriter and DelimitedLineAggregator to support Hive/HAWQ CSV standards.",
    "MessageBus transformation optimization (U8) will refactor payload handling to stream-based or zero-copy byte buffer transformations to minimize GC pressure and increase throughput."
  ],
  "assumptions": [
    "Development work is performed on an existing Spring-based batch/data integration framework codebase.",
    "Development environment includes standard JDK 17, Gradle/Maven build tools, and automated CI/CD pipelines.",
    "Single developer will perform design, implementation, unit testing, integration testing, and documentation.",
    "Effort is expressed in standard workdays (8 productive working hours per day)."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Technical Design & API Specification",
      "activity_description": "Analyze requirements across U1-U8, design public API modifications, data models, and component interfaces, and draft architectural guidelines.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Implement Parameterized CodeGen Options (U1)",
      "activity_description": "Develop configuration models and builder API for CodeGen options, allowing dynamic runtime code generation parameterization and unit testing.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Implement Parameterized Merge Options (U2)",
      "activity_description": "Implement configurable Merge Options API and integrate with megastore delta consumption logic, including unit tests.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Implement Job & Task Execution Timeout (U3)",
      "activity_description": "Add timeout properties to job and step definitions, implement thread monitoring and interruption logic for hung states, and test timeout handling.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Implement SQL Statement/Script Execution Component (U4)",
      "activity_description": "Create SQL Execution Processor and Tasklet supporting inline SQL and external script files with variable bindings and transaction management.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Support Custom RowMapper<Tuple> in JDBC Readers (U5)",
      "activity_description": "Refactor NameColumnJdbcItemReader and ItemReaderFactory to accept custom RowMapper<Tuple> for field enrichment without recreating immutable tuples.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Implement SpEL Expression Support for Dynamic Naming (U6)",
      "activity_description": "Integrate SpEL expression parser into file/directory resource resolvers to enable dynamic pathing based on timestamps and intermediate context.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Implement Delimiter Escaping in CSV/Delimited Writers (U7)",
      "activity_description": "Add escape character support to line aggregators and writers, ensuring Hive and HAWQ compliant CSV formatting.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Refactor MessageBus Transformer Engine (U8)",
      "activity_description": "Optimize programmatic message transformation logic in MessageBus to improve throughput performance, including micro-benchmarking.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "System Integration Testing, Performance Benchmarking & Docs",
      "activity_description": "Perform end-to-end integration testing for all user stories, verify performance improvements for U8, and update framework developer documentation.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 27
  }
}
